  $('busScan').textContent=`IÂ²C${bus}: SDA/SCL ${reply[1]}/${reply[2]} â†’ ${reply[3]}/${reply[4]} Â· `+
    `${reply[5]} timeouts Â· ${reply[6]} NACKs Â· found ${addresses.join(', ') || 'none'}`;
